import type { SVGProps } from "react";
import { cn } from "@/lib/utils";

export type EmrSidePanelStateIconState =
  | "cancel"
  | "done"
  | "in-progress"
  | "rework"
  | "stop"
  | "to-do";

type EmrSidePanelStateIconProps = Omit<SVGProps<SVGSVGElement>, "children" | "color"> & {
  state: EmrSidePanelStateIconState;
};

const roundedSquarePath =
  "M6 0.75H10C12.8995 0.75 15.25 3.10051 15.25 6V10C15.25 12.8995 12.8995 15.25 10 15.25H6C3.10051 15.25 0.75 12.8995 0.75 10V6C0.75 3.10051 3.10051 0.75 6 0.75Z";
