  "M0.75 6.75C0.75 3.43629 3.43629 0.75 6.75 0.75H10.75C14.0637 0.75 16.75 3.43629 16.75 6.75V10.75C16.75 14.0637 14.0637 16.75 10.75 16.75H6.75C3.43629 16.75 0.75 14.0637 0.75 10.75V6.75Z";

export function EmrSidePanelStateIcon({
  className,
  state,
  ...props
}: EmrSidePanelStateIconProps) {
  const viewBox = state === "cancel" ? "0 0 18 18" : "0 0 16 16";

  return (
    <svg
      {...props}
      className={cn("size-[var(--emr-sidepanel-state-icon-size)] shrink-0", className)}
      data-state-icon-state={state}
      viewBox={viewBox}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
    >
      {state === "done" ? <DoneStateIcon /> : null}
      {state === "in-progress" ? <InProgressStateIcon /> : null}
      {state === "to-do" ? <TodoStateIcon /> : null}
      {state === "cancel" ? <CancelStateIcon /> : null}
      {state === "rework" ? <ReworkStateIcon /> : null}
      {state === "stop" ? <StopStateIcon /> : null}
    </svg>
  );
}

